(x, y, t) => {
  const cx = 240, cy = 120;
  const warp1 = Math.sin(x * 0.018 + t * 0.25) * 18 + Math.cos(y * 0.013 - t * 0.18) * 12;
  const warp2 = Math.cos(y * 0.016 - t * 0.22) * 16 + Math.sin(x * 0.02 + t * 0.3) * 11;
  const warp3 = Math.sin((x + y) * 0.01 + t * 0.15) * 8;
  const sx = x + warp1 + warp3, sy = y + warp2 + warp3;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.075, 2.1],
    [320+Math.cos(t*0.45)*105, 160+Math.sin(t*0.65)*55, 0.095, 1.8],
    [240+Math.sin(t*0.28+2)*145, 120+Math.cos(t*0.48+1)*95, 0.055, 2.4],
    [100+Math.cos(t*0.75+1)*85, 190+Math.sin(t*0.55+3)*65, 0.11, 1.6],
    [370+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.85+2)*75, 0.065, 2.7],
    [240+Math.cos(t*0.32+5)*125, 210+Math.sin(t*0.52)*85, 0.085, 2.0],
    [60+Math.sin(t*0.6+1.5)*70, 40+Math.cos(t*0.7+0.5)*50, 0.1, 1.4],
    [420+Math.cos(t*0.42+3)*60, 200+Math.sin(t*0.58+2)*55, 0.08, 2.2]
  ];
  let aS = 0, iS = 0, feed = 0, kill = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx - sX) ** 2 + (sy - sY) ** 2);
    aS += Math.sin(d * f - t * sp);
    iS += Math.sin(d * f * 0.7 + t * sp * 0.6 + 1.5);
    feed += Math.cos(d * f * 0.4 - t * sp * 0.3 + 2.8) * 0.5;
    kill += Math.sin(d * f * 1.1 + t * sp * 0.45 - 1.2) * 0.4;
  }
  const n = src.length;
  const act = aS / n, inh = iS / n, fd = feed / n, kl = kill / n;
  const dist = Math.sqrt((sx - cx) ** 2 + (sy - cy) ** 2);
  const ang = Math.atan2(sy - cy, sx - cx);
  const spiral = (Math.sin(dist * 0.045 - ang * 4 - t * 1.6) + Math.sin(dist * 0.035 + ang * 5 - t * 1.1) + Math.sin(dist * 0.06 - ang * 2 + t * 0.8)) / 3;
  const moire = (Math.sin(sx * 0.12 + sy * 0.08) * Math.sin(sx * 0.08 - sy * 0.12 + t * 0.5) + Math.sin((sx - sy) * 0.1 + t * 0.7)) * 0.3;
  const bg = (Math.sin(sx * 0.035 + sy * 0.022 + t * 0.75) + Math.sin(sx * 0.028 - sy * 0.038 + t * 1.05)) / 2 + Math.sin((sx + sy) * 0.11 + t * 2.3) * 0.15 + Math.sin((sx - sy) * 0.09 - t * 1.8) * 0.15;
  const laplacian = (Math.sin(sx * 0.08) + Math.sin(sy * 0.08) + Math.sin((sx + sy) * 0.056) + Math.sin((sx - sy) * 0.056)) * 0.25;
  const rd = act + fd * 0.4 - act * inh * 0.15 - act * kl * 0.1;
  const diffusion = rd + (laplacian - rd) * 0.35;
  const pattern = Math.tanh((diffusion * 0.7 + inh * 0.25 + bg * 0.2 + spiral * 0.35 + moire * 0.15) * 2.0);
  const cell = Math.tanh((Math.sin(sx * 0.14) * Math.sin(sy * 0.14) + Math.sin((sx + sy) * 0.095 + t) * 0.5 + Math.sin(sx * 0.07 - sy * 0.11 + t * 0.4) * 0.3) * 1.4) * 0.2;
  const micro = Math.sin(sx * 0.3 + t * 2) * Math.sin(sy * 0.3 - t * 1.7) * 0.08;
  const blend = pattern * 0.65 + cell * 0.2 + micro;
  const v = blend * 0.5 + 0.5;
  const pal = [
    [5, 12, 58], [12, 45, 95], [18, 85, 120], [25, 135, 130],
    [60, 170, 115], [140, 195, 80], [210, 185, 55], [225, 145, 60],
    [215, 100, 65], [185, 60, 70], [130, 35, 65], [70, 18, 55], [5, 12, 58]
  ];
  const idx = v * (pal.length - 1);
  const i = Math.min(idx | 0, pal.length - 2);
  const f = idx - i;
  const energy = Math.abs(pattern);
  const lum = 0.75 + energy * 0.3 + Math.sin(pattern * Math.PI) * 0.1;
  const edge = energy > 0.65 ? 1.18 : energy > 0.4 ? 1.05 : 0.95;
  const glow = energy > 0.8 ? (energy - 0.8) * 0.5 : 0;
  return [
    Math.min(255, ((pal[i][0] + (pal[i + 1][0] - pal[i][0]) * f) * lum * edge + glow * 40) | 0),
    Math.min(255, ((pal[i][1] + (pal[i + 1][1] - pal[i][1]) * f) * lum * edge + glow * 30) | 0),
    Math.min(255, ((pal[i][2] + (pal[i + 1][2] - pal[i][2]) * f) * lum * edge + glow * 15) | 0)
  ];
}
